class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        adict = {'2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl', '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'}
        res = []

        def backtrack(path, cur):
            if cur == len(digits):
                res.append(''.join(path[:]))
                return
            for choice in adict[digits[cur]]:
                path.append(choice)
                backtrack(path, cur + 1)
                path.pop()

        backtrack([], 0)
        return res
